"""Draft 49 checked DESeq2 roles, retaining units, wrappers and unresolved declarations."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
HERE=ROOT/'tools/literature';BASE=ROOT/'build/literature-review/deseq2-runtime'
# Summary, implementation boundary, explicitly supported edition, supporting paragraph indices.
NOTES={
'P004':('Used DESeq2 1.34.0 to compare ATAC-seq accessibility in 50-kb bins between alpha-amanitin-treated and untreated samples, retaining bins with adjusted P<0.05. The same analysis describes CPM/log-transformed profiles separately.', 'The count-bin test is distinct from CPM/log-profile visualization. The paragraph does not establish that transformed profiles were DESeq2 count inputs; do not pass CPM or log values as raw counts. Bin construction and paper-specific design remain separate.', '1.34.0',[]),
'P007':('Tested expression differences using a DESeq2 likelihood-ratio model including cell condition and species. Repeated analysis after aligning to human and ape references, adjusted P values by BH and described fold-change shrinkage. Cross-reference agreement and direction filters selected final genes.', 'The reduced model and shrinkage method are unstated. Prepare both count populations and explicit model/contrasts; do not infer a reduced model, current shrinker or historical edition. Agreement/direction criteria across alignments are downstream operations.',None,[]),
'P013':('Used DESeq2 1.22.2 after excluding genes with zero counts in all samples, estimated size factors and produced regularized-log values. Compared samples with MEFs at 72 h using results with lfcThreshold=1, altHypothesis=greaterAbs and alpha=0.05; transformed values supported exploratory comparisons.', 'Preserve the reported threshold test rather than replacing it with a post hoc fold-change filter. Current 1.52.0 greaterAbs behavior is not certified as identical to the older test. Correlation, variable-gene selection and PCA remain downstream.', '1.22.2',[]),
'P016':('Used DESeq2-normalized RNA-seq gene counts for expression comparisons and MA plots between control and knockout mice, identifying changes at adjusted P<0.05. Normalized counts also supported gene-expression displays; PCA excluded Olfr genes.', 'The DESeq2 edition, full design and effective statistical options are unstated. Mapping/read filtering, MA/PCA graphics and gene exclusion for PCA remain separate; normalized output is not a replacement for raw fit inputs.',None,[]),
'P018':('Called DESeq2 1.14.1 through HOMER 4.10 getDiffExpression.pl, using the described default normalization and replicate-based dispersion handling. Selected differentially expressed genes at BH-adjusted P<0.05.', 'The adapter does not reconstruct the HOMER wrapper or the complete historical 1.14.1 environment. Supply prepared counts and explicit current-model options; do not assume historical wrapper defaults match current DESeq2.', '1.14.1',[]),
'P020':('Used DESeq2 1.22.2 for RNA-seq differential expression with adjusted P<0.05 and absolute log2 fold change>1. A separate human post-versus-pre analysis used a DESeq2 negative-binomial Wald test and BH correction before pathway analyses.', 'The reported fold-change cutoff is a selection criterion, not evidence of lfcThreshold hypothesis testing. The second call does not state its edition. GSVA/GSEA and sample preparation remain separate.', '1.22.2',[35]),
'P029':('Used DESeq2 1.48.1 with described default settings for differential gene expression from featureCounts-derived RNA-seq counts.', 'The effective design, contrast and statistical thresholds are not specified in this paragraph. The current 1.52.0 runtime is explicit and does not silently substitute for a historical package; featureCounts preparation remains separate.', '1.48.1',[]),
'P031':('Used DESeq2 1.26.0 on raw counts in human M-cell single-cell analysis and on mouse M-cell/enterocyte comparisons, and separately analyzed bulk M-cell organoid RNA-seq. Reported context-specific fold-change/P cutoffs; the statistics section describes a two-sided negative-binomial Wald test.', 'Do not infer donor pseudobulking or relabel reported P cutoffs as adjusted P. Human marker criteria include absolute log2FC>=2 and P<=0.001; bulk criteria include absolute log2FC>=1 and P<=0.01. Enrichr, GSEA and Fisher tests are separate.', '1.26.0',[57,71,73]),
'P032':('Used DESeq2 1.32.0 for donor-adjusted RNA/ADT pseudobulk perturbation comparisons. Separate uses include bulk RNA-seq with size factors estimated across all samples, CUT&RUN mark differences and size-factor-scaled tracks, and variance stabilization for activation-gene selection before GSVA scoring.', 'Preserve the full normalization population before explicit row/subset selection. This adapter does not construct pseudobulk/ADT counts, CUT&RUN peaks/tracks, activation gene sets or GSVA scores. One prepared fit is not the complete multi-assay pipeline.', '1.32.0',[40,51,56]),
'P037':('Used DESeq2 1.34.0 variance stabilization on the unfiltered Kallisto count population before retaining 837 MAGs selected using TPM>5 in more than 40% of 707 samples. Transformed abundances then entered linear mixed models relating MAGs to WLZ.', 'Run the transformation on the unfiltered population and select rows afterwards. keep_genes before transformation would change this sequence. Kallisto estimated-count preparation is unstated; TPM filtering and the subsequent mixed models are separate.', '1.34.0',[]),
'P040':('Used DESeq2 1.48.2 for bulk stimulated-T-cell expression differences from HOMER/RefSeq-derived counts, after an expression filter described using RPKM. Selected genes at adjusted P<0.05 and absolute log2FC>0.5.', 'Use the underlying count matrix, not RPKM as raw counts. The expression filter and post hoc fold-change cutoff do not establish a thresholded Wald test. HOMER/count construction and exact model settings remain separate.', '1.48.2',[]),
'P044':('Used DESeq2 1.26.0 to identify differential accessibility in an ATAC-seq peak atlas built around summits extended by 500 bp in each direction.', 'Peak/atlas construction, read counting and HOMER motif analysis are separate requirements. The paragraph does not state all model/contrast settings; current original-runtime fitting does not certify the historical full pipeline.', '1.26.0',[]),
'P046':('Used DESeq2 for multifactor RNA-seq differential expression accounting for genotype and individual, and regularized-log transformation for clustering. Separately used DiffBind 3.4.11 with DESeq2 for differential accessibility at FDR<0.01.', 'The DESeq2 edition is unstated. TMM/RPKM descriptions must not be silently treated as raw counts. limma removeBatchEffect, clustering, DiffBind peak preparation and wrapper behavior remain separate.',None,[32]),
'P049':('Reported DESeq2 1.44 for human retinal pseudobulk comparisons. Additional calls compared resilient/susceptible RGC groups, normalized and regularized-log-transformed five bootstrap populations of 100 nuclei for resilience regression, reanalyzed EAE mouse RNA-seq and analyzed neuronal Cfh-knockout cultures.', 'The patch edition is unstated. Bootstrap construction, Seurat aggregation, AUCell, resilience linear models and other downstream tests are separate. Preserve biological replication and each normalization population; bootstraps are not independent biological donors.', '1.44',[37,38,47,57]),
'P050':('Used the default DESeq2 analysis in iDEP 0.96 for RNA-seq. A separate ATAC-seq analysis counted peak reads with featureCounts and used DESeq2 with two biological replicates.', 'The underlying DESeq2 edition and full iDEP options are unstated. Do not infer adjusted P from the paper\'s P wording or treat a displayed fold-change cutoff as an lfcThreshold test. iDEP and peak/count preparation are separate.',None,[47]),
'P051':('Used DESeq2 1.30.1 with a likelihood-ratio test to find genes changing across experimental conditions in bulk neutrophil RNA-seq. Pairwise comparisons in the same analysis used limma/edgeR separately.', 'Do not attribute limma/edgeR pairwise tests or downstream k-means clustering to DESeq2. An explicit full/reduced design is required for the current LRT; unstated historical options are not inferred.', '1.30.1',[]),
'P052':('Reported Azenta RNA-seq differential-expression analysis using DESeq2 after aligning STV-C8 RNA reads to the human transcriptome with STAR.', 'The DESeq2 edition, exact count preparation, model and cutoffs are unstated. STAR alignment, vendor workflow and characterization of vesicle RNA content are separate; no whole-vendor-pipeline equivalence is claimed.',None,[]),
'P079':('Used DESeq2 for expression differences between clone-specific ART-related and expected unrelated samples, referring to a TRACERx method and Supplementary Note 31 for details.', 'Edition and effective model/contrast settings remain unresolved from the checked main text. The cited supplementary method is not reconstructed here. Clone assignment and ART/ctDNA analysis are separate.',None,[]),
'P082':('Listed DESeq2 among software used in Code availability for the complex-karyotype AML single-cell multiomics study. The checked main-text Methods and eight retained author R Markdown scripts do not establish a particular DESeq2 analysis call.', 'Exact DESeq2 role and edition remain unresolved. Do not attribute the separately described scran Welch marker tests, linear models or scNOVA discriminant analysis to DESeq2. This is a reviewed software-use declaration, not a reproduced differential-expression workflow.',None,[]),
'P086':('Used DESeq2 varianceStabilizingTransformation for each bulk transcriptome dataset, followed by described z scoring/merging and batch correction, then exploratory UMAP and gene comparisons. The paper attributes ComBat_seq to the DESeq2 package.', 'Preserve the attribution discrepancy: ComBat_seq belongs to sva, not DESeq2. Its raw-count contract and the reported transformed/z-scored sequence need resolution; do not substitute ComBat or coerce transformed values to counts. Batch correction and UMAP are separate.',None,[]),
'P088':('Reported DESeq2 1.20.0 for cardiac cell-type analyses. The checked supplement describes DESeq2 normalization of donor/cell-type pseudobulk counts after edgeR filtering, followed by limma-voom tests for cell-type programs and DCM-versus-control differences. Disease testing used disease and sex covariates with BH correction.', 'Credit DESeq2 normalization, not limma-voom differential tests or stratified-LDSC heritability. Supplement physical pages 69,71–73 specify distinct populations/designs; filtering, pseudobulking, limma-voom and gene-program/SNP annotation remain separate. Exact normalization options are unstated.', '1.20.0',[38,41]),
'P092':('Used DESeq2 varianceStabilizingTransformation on read counts to visualize accessibility at significant caQTLs with box plots.', 'This use is normalization/transformation for visualization, not evidence that DESeq2 mapped caQTLs. The edition and transformation options are unstated; QTL fitting and plotting remain separate.',None,[]),
'P096':('Used DESeq2 1.40.1 for age-dependent single-nucleus expression analysis. The supplement sums raw counts by cluster/sample, collapses technical replicates, filters genes expressed in>10% of nuclei and uses design single_cell_chemistry+age_group with a Wald test and BH adjustment. Positive fold changes indicate paediatric expression.', 'The supplement supports chemistry adjustment and biological-replicate aggregation, not arbitrary cell-level independence. PCA/dispersion diagnostics, pathway enrichment and pseudotime analysis remain separate. Current runtime execution is not historical 1.40.1 whole-environment reproduction.', '1.40.1',[47,48]),
'P098':('Used DESeq2 1.40.2 median-of-ratios normalization, pairwise two-sided Wald tests, BH correction and fold-change shrinkage, with adjusted P<0.05 and absolute log2FC>1 selection. Used VST across all samples for individual-gene comparisons.', 'The paragraph explicitly reports 1.40.2 despite the initial extractor missing it. The shrinker is unspecified; do not infer apeglm/ashr. The fold-change selection is not an explicit threshold test. rstatix/Holm and t/Wilcoxon comparisons are separate.', '1.40.2',[]),
'P101':('Used DESeq2 1.32.0 for wild-versus-domesticated gene-expression differences after featureCounts quantification, with adjusted P<=0.05 and a reported absolute fold-change cutoff>=1.5.', 'Preserve the source\'s fold-change units; do not silently turn 1.5 into a log2 threshold. Count preparation, sample/model choices and GO enrichment are separate.', '1.32.0',[]),
'P108':('Used DESeq2 1.38.3 variance stabilization in expression reference-panel processing for GTEx, developmental brain and adult brain analyses, alongside described TMM/log-CPM normalization, batch handling and residualization before predictive/QTL models.', 'The reported order and count units across TMM, VST, log-space and residualization are ambiguous. Do not pass normalized floating values as raw counts or silently rewrite the sequence. ComBat/SVA, PEER/HCP and QTLtools are separate.', '1.38.3',[47,51]),
'P110':('Used DESeq2 on Kallisto est_counts RNA-seq quantifications, selecting differential expression at adjusted P<0.01.', 'The edition and estimated-count import/rounding procedure are unstated. Do not silently round or substitute TPM as counts. The adapter supports explicit R-round handling when requested; that capability does not establish the paper\'s procedure.',None,[]),
'P113':('Used DESeq2 default median-abundance size factors and fold-change results for EU-seq, then subtracted the median fold change of expressed genes. Also normalized 12 replicates before matched treated/control ratios, log2 conversion, median adjustment and averaging over time points; size factors scaled genome-browser tracks.', 'Median-centering and matched-ratio calculations are custom downstream operations, not automatic DESeq2 inference. Preserve each normalization cohort; track generation and regulatory classification remain separate. Edition/model details are unstated.',None,[79]),
'P121':('Used DESeq2 1.30.1 on explicitly rounded RSEM counts with a paired experimental-replicate/genotype design and three replicates. Used adjacent-stage information for dispersion estimation, disabled independent filtering for reported contrasts and selected changes at FDR<0.05 and fold change>1.25.', 'Preserve explicit R rounding, sample populations and independentFiltering=FALSE. The cutoff is post hoc, not evidence of a thresholded hypothesis. Do not silently resolve genotype-label spelling or construct RSEM/adjacent-stage cohorts.', '1.30.1',[]),
'P124':('Used DESeq2 for guide-abundance differences in FACS screens, RNA-seq Wald tests and ATAC-seq differences; only the ATAC-seq paragraph explicitly reports version 1.36. Guide results fed empirical controls and mRRA gene aggregation, and CRISPR-knockout guide comparisons were followed by MAGeCK gene analysis.', 'Version 1.36 applies to the ATAC-seq context; other calls do not state their edition. Empirical null/P calculations, ten-million-null mRRA aggregation, weighted guide effects, MAGeCK and sequencing preparation are separate.',None,[47,53,55,63]),
'P133':('Used DESeq2 Wald statistics to rank genes for fgsea, and separately fit RNA-seq PTGES3 knockdown/control and ATAC-seq accessible-region differences, applying adjusted P<0.05 and absolute log2FC>1 selection.', 'The edition and effective models are unstated. Do not replace post hoc fold-change selection with lfcThreshold testing. fgsea, STRING analysis and accessible-region/count preparation remain separate.',None,[36,40]),
'P137':('Used DESeq2 variance stabilization for between-sample comparisons of the same gene. TPM was described separately for constitutive gene-expression comparisons; an EPICC 2.Rmd script was referenced.', 'The edition, exact VST settings and referenced script call are not established here. TPM is not a raw-count input. Gene-expression summaries and the complete EPICC workflow remain separate.',None,[]),
'P139':('Used DESeq2 for expression changes in BET-inhibitor-treated cardiomyocytes, keeping genes with at least 10 counts across replicates before differential analysis.', 'Edition and full model options are unstated. Preserve the reported filtering population instead of guessing per-sample filtering. BET sensitivity assays, transcription-factor binding and other downstream analyses are separate.',None,[]),
'P145':('Used DESeq2 1.40.2 on cell-type pseudobulk profiles from SoupX-corrected counts, estimating size factors on the unfiltered pseudobulk population before fitting filtered genes. Adjusted mitochondrial/ambient/batch covariates and selected FDR<0.05, absolute log2FC>0.5. A separate dementia comparison used 70 donors and eight covariates.', 'Preserve the unfiltered normalization cohort and distinct covariate designs. SoupX correction, pseudobulk generation and rounding are not supplied or inferred. The post hoc fold-change criterion is not a thresholded Wald test.', '1.40.2',[55]),
'P151':('Imported Salmon quantification through tximport and used DESeq2 contrasts across baseline/stimulation and targeting/scrambled conditions, separately for CRISPR activation/inhibition, after low-count filtering with alpha=0.05. Also reanalyzed TL1A gene counts.', 'The adapter does not implement tximport quantifier import or transcript-length offset construction. Prepared counts and any required normalization factors must be explicit. Do not equate a plain rounded count matrix with the complete Salmon/tximport pipeline.',None,[]),
'P155':('Used DESeq2 for RNA-seq expression analysis; the paragraph attaches version 1.14.1 to wording that mentions both the DESeq2 package and R.', 'The version attribution is ambiguous, so the DESeq2 edition remains null rather than guessing that 1.14.1 is the package or R edition. Supply explicit count/model settings; no historical whole-environment claim is made.',None,[]),
'P163':('Used DESeq2 for RNA-seq normalization/differential expression and Wald-based gene ranking, and VST for ATAC-seq clustering. For chromatin comparisons with n>2, DiffBind 3.12 used DESEQ2 at FDR<0.1; n=1 comparisons used a different Goodpeaks script.', 'Do not attribute n=1 Goodpeaks comparisons to DESeq2. DiffBind preparation, gene-ranking construction, fgsea, binarization/k-means and hypergeometric tests remain separate. The DESeq2 edition is unstated.',None,[66,70]),
'P165':('Used DESeq2 for bulk RNA-seq differential expression and ranked genes by descending log fold change for GSEA.', 'The edition and effective model/contrast options are unstated. GSEA and sequencing/count preparation are separate; ranking capability does not reproduce the full pathway workflow.',None,[]),
'P172':('Used DESeq2 on Rsubread gene/exon read counts for wild-type versus MAX Arg60Gln transcriptome comparisons. The results describe filtering genes with fewer than five reads in all samples, retaining 20,868 genes and selecting adjusted P<0.05.', 'Preserve the stated filtering rule and genotype comparison. The edition and full model options are unstated. Rsubread counting, c-Myc target interpretation and Reactome analysis remain separate.',None,[22]),
'P176':('Used DESeq2 median-of-ratios normalization before estimating unwanted technical variation with SVA and residualizing expression values.', 'SVA fitting and residualization are separate operations, not DESeq2 features. The edition and effective normalization population are unstated; do not feed residualized expression back as raw counts.',None,[]),
'P183':('Used DESeq2 for lncRNA, circRNA and protein-coding gene differences in schizophrenia/control organoids and neuronal/nonneuronal populations. lncRNA/protein-coding filters used TPM>0.1 and more than six reads in at least 20% of samples; BH-adjusted P<0.05 selected differences.', 'The TPM/read filters do not establish TPM as DESeq2 raw input. Preserve the distinct 8+8 organoid and 10+10 neuronal populations; edition and full model details are unstated. circRNA/count construction remains separate.',None,[]),
'P187':('Used EDASeq GC correction and DESeq2 size factors for cell-type ATAC marker comparisons, retaining mean counts>=10 and differential peaks at FDR<0.05. Additional caQTL/eQTL workflows used DESeq2 normalization/VST before inverse-normal transformation and FastQTL.', 'EDASeq normalization factors, inverse-normal transformation and FastQTL fitting are separate. Do not attribute QTL association tests to DESeq2 or assume an unprovided factor matrix equals the paper\'s GC correction. caQTL/eQTL windows and covariates remain explicit external steps.',None,[18,21]),
'P197':('Reported DESeq2 normalization and differential expression after Salmon transcriptome quantification, with P<0.05 and absolute log2FC>1.5 selection. The paragraph states R 4.2.2.', 'R 4.2.2 is not a DESeq2 edition. Count import/rounding and whether the reported P is adjusted are unresolved; do not infer either. Salmon preparation and pathway interpretation remain separate.',None,[]),
'P215':('Used raw gene counts from Kallisto as DESeq2 inputs for control-versus-CSS expression differences, reporting P<0.05 and FDR<5%. TPM values were used separately in violin plots.', 'Keep the explicit raw-count versus TPM-display distinction. The edition, estimated-count import details and full model settings are unstated; no silent rounding or whole Kallisto pipeline is supplied.',None,[]),
'P220':('Used DESeq2 1.42.0 to normalize RSEM transcript counts in adipose cells. In CRISPR adipocyte RNA-seq, removed raw counts below 10 and compared with the Cas9 empty baseline. A separate pathway analysis used regularized-log-transformed counts for GSEA.', 'RSEM/count preparation, filtering details and GSEA are separate. Preserve the reported ranking/direction convention; rlog output does not itself implement pathway testing. Exact historical runtime equivalence is not certified.', '1.42.0',[48,51]),
'P226':('Reported Salmon TPM quantification followed by differential expression with DESeq2 through Galaxy.', 'The reported TPM input is inconsistent with the raw-count contract of this adapter. Preserve the unit discrepancy; obtain the actual count/import procedure rather than converting TPM to counts, rounding it or claiming the Galaxy workflow is reproduced. Edition is unstated.',None,[]),
'P228':('Used DESeq2 Wald testing with adjusted P<0.1 and removed Y-chromosome genes downstream. A separate comparison collapsed technical replicates with collapseReplicates and described a one-sided Wald test for SMS downregulation versus control.', 'Preserve technical versus biological replicate identity. The actual one-sided results arguments are not supplied; DESeq() alone does not select them. Explicit less testing demonstrates current capability without establishing the paper\'s unreported arguments. Edition is unstated.',None,[15]),
'P248':('Used DESeq2 R package 1.30.1 for RNA-seq differential expression, selecting adjusted P<0.05 and absolute log2FC>=1. FPKM/TPM quantifications were described separately in the broader expression/QTL workflow.', 'The paragraph explicitly states 1.30.1 despite the initial extractor missing it. Do not use FPKM/TPM as raw counts or turn the post hoc cutoff into lfcThreshold testing. Count import, eQTL/TWAS and sample preparation remain separate.', '1.30.1',[]),
'P249':('Described correction of raw TPM values across tissues with the default DESeq2 function before pangenome-derived allele expression comparisons.', 'Preserve the reported raw-TPM wording and unresolved function/count-unit discrepancy. This adapter requires raw counts or explicitly declared estimated-count rounding; it does not convert TPM to counts. Edition and effective call are unstated.',None,[])
}

def digest(raw):return hashlib.sha256(raw).hexdigest()
def write(path,obj):assert not path.exists();path.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n',encoding='utf8',newline='\n')

def main():
    audit=json.loads((BASE/'catalog-primary-role-audit-2/PRIVATE-PRIMARY-USES.json').read_bytes());assert (audit['papers_scanned'],audit['catalogued_papers'],audit['mentioned_papers'])==(250,47,49) and {r['paper_id'] for r in audit['records']}==set(NOTES)
    current=json.loads((HERE/'reviewed-uses.json').read_bytes());prior=[r for r in current['reviews'] if r['tool_id']=='deseq2'];assert len(current['reviews'])==832 and len(prior)==1 and prior[0]['pmcid']=='PMC11525197'
    drafts=[];additions=[]
    for row in audit['records']:
        pid=row['paper_id'];summary,scope,version,indices=NOTES[pid];allp={p['paragraph_index']:p for p in row['named']+row['neighbors']}
        if row['anchor']:anchor=row['anchor'];index=anchor['evidence_paragraph_index'];h=anchor['evidence_paragraph_sha256']
        else:
            index={'P082':64,'P088':59}[pid];source=allp[index];h=source['sha256'];assert source['section']=='Code availability'
            additions.append(dict(paper_id=pid,pmcid=row['pmcid'],doi=row['doi'],xml_sha256=row['xml_sha256'],paragraph_index=index,section=source['section'],paragraph_sha256=h,analysis_role='Declared software; exact DESeq2 analysis role unresolved' if pid=='P082' else 'Pseudobulk count normalization before limma-voom',usage_context='reported-software-list-role-unresolved' if pid=='P082' else 'normalization-method-description'))
        support=[]
        for i in indices:
            source=allp.get(i)
            if source is None:
                # Canonical non-named details may be outside adjacent paragraphs.
                import gzip,xml.etree.ElementTree as ET
                from collect_omics_review import paragraphs
                raw=gzip.decompress((ROOT/'build/literature-review/xml'/(row['pmcid']+'.xml.gz')).read_bytes());assert digest(raw)==row['xml_sha256'];source=next(p for p in paragraphs(ET.fromstring(raw)) if p['paragraph_index']==i);source=dict(source,sha256=digest(source['text'].encode('utf8')))
            pointer=dict(paragraph_index=i,section=source['section'],paragraph_sha256=source['sha256'])
            if pid=='P088':pointer.update(evidence_role='method-details',named_anchor=dict(paragraph_index=index,section='Code availability',paragraph_sha256=h),shared_terms=['cell-type-specific'],relation_note='The named software declaration identifies cell-type-specific heritability preparation; these Methods paragraphs describe the cardiac cell-type analyses whose exact normalization/testing roles are detailed in the checked supplement.')
            support.append(pointer)
        review=dict(pmcid=row['pmcid'],doi=row['doi'],tool_id='deseq2',evidence_paragraph_sha256=h,use_summary=summary,implementation_scope_note=scope,version_reported_near_name=version,usage_context='reported-software-list-role-unresolved' if pid=='P082' else 'normalization-method-description' if pid=='P088' else 'analysis-method-description',supporting_evidence=support)
        drafts.append(dict(paper_id=pid,review=review))
    write(HERE/'deseq2-source-additions.json',dict(schema_version=1,status='checked-two-named-DESeq2-software-declarations',frozen_collector_sha256=digest((HERE/'collect_omics_review.py').read_bytes()),declarations=additions,scope='Only exact reviewed Code availability declarations; no generic availability extraction or inference of statistical testing. P082 exact role unresolved; P088 normalization established by supplement.'))
    write(HERE/'deseq2-use-reviews.json',drafts)
    sources=[]
    for pid,doi,stem,pages,role in [('P088','10.1038/s41588-024-01975-5','41588_2024_1975_MOESM1_ESM.pdf',[69,71,72,73],'DESeq2 normalization before limma-voom, with separate cell-type-program and disease/sex models; no DESeq2 heritability or differential-testing attribution.'),('P096','10.1038/s41588-024-01990-6','41588_2024_1990_MOESM1_ESM.pdf',[2,3,11,12],'Raw-count pseudobulk/technical collapse, cell chemistry plus age-group design, Wald/BH testing, paediatric-positive fold changes and significance definitions.')]:
        f=BASE/'supplement-source-intake-2'/stem;url='https://media.springernature.com/full/springer-static/esm/art%3A'+doi.replace('/','%2F')+'/MediaObjects/'+stem
        sources.append(dict(paper_id=pid,doi=doi,url=url,bytes=f.stat().st_size,sha256=digest(f.read_bytes()),physical_PDF_pages=pages,paraphrased_role=role))
    code=BASE/'code-source-intake-1/source';notebooks=sorted(code.rglob('*.Rmd'));assert len(notebooks)==8
    import re
    assert not any(re.search(r'DESeq2|\brlog\b',p.read_text(encoding='utf8'),re.I) for p in notebooks)
    write(HERE/'deseq2-additional-source-evidence.json',dict(schema_version=1,status='checked-primary-supplement-and-author-code-locators-not-whole-pipeline-reproduction',supplements=sources,P082=dict(author_repository='https://github.com/amleppa/scNOVA-CITE_paper',inspected_reference_commit='34dba322b1be72b40ca4c0e76fe31fada5668f66',paper_exact_checkout_known=False,latest_prepublication_reference_commit='5a7f279e8c7123039956f0dacf303149f21bad61',inspected_reference_is_later_than_publication=True,notebooks=[dict(path=p.relative_to(code).as_posix(),bytes=p.stat().st_size,sha256=digest(p.read_bytes())) for p in notebooks],direct_DESeq2_or_rlog_call_found=False,role='Explicit software-use declaration; exact DESeq2 analysis role remains unresolved. Do not assign scran or scNOVA tests to DESeq2.'),long_primary_text_or_author_code_published=False))
    print(json.dumps(dict(status='drafted-49-DESeq2-primary-role-reviews-not-applied',reviews=49,source_additions=2,supporting_pointers=sum(len(r['review']['supporting_evidence']) for r in drafts),initial_observations=2442,proposed_observations=2444,unresolved_P082_role=True,version_corrections=['P049:1.44','P098:1.40.2','P248:1.30.1'])))

if __name__=='__main__':main()
